import { AnimatePresence, MotiView } from 'moti'
import { CodePreviewContainer } from './CodePreviewContainer'
import { CodeChangePlaceholderBlock } from './blocks/CodeChangePlaceholderBlock'
import { CodeChangeBlock } from './blocks/CodeChangeBlock'
import { defineStyles } from '@/utils/defineStyles'
import { colors, Theme, useTheme } from '@/theme'
import { UIBlockData } from './UIBlock'

interface CodeBlockData {
	data: UIBlockData
	isLoading: boolean
	placeHolderText: string[]
	currentPlaceholderIndex: number
}

export const CodeBlock = ({
	data,
	isLoading,
	placeHolderText,
	currentPlaceholderIndex
}: CodeBlockData) => {
	const { theme } = useTheme()

	const isCancelled = data.status === 'cancelled'
	const shouldShowCodePreview = isLoading && data.code !== ''
	const hasEnoughContent = !!data.code && data.code.trim().length > 0

	const showCodePreview = shouldShowCodePreview && hasEnoughContent

	return (
		<AnimatePresence exitBeforeEnter>
			{showCodePreview && !!data.code && (
				<CodePreviewContainer code={data.code} />
			)}
			{isLoading && !showCodePreview && (
				<MotiView
					key="code-placeholder"
					from={{ opacity: 0, translateY: -6 }}
					animate={{ opacity: 1, translateY: 0 }}
					exit={{ opacity: 0, translateY: 6 }}
					transition={{ type: 'timing', duration: 300 }}
					style={[styles.fileChangeContainer(theme), styles.alignCenter]}
				>
					<CodeChangePlaceholderBlock
						isCancelled={isCancelled}
						placeholderText={placeHolderText[currentPlaceholderIndex]}
					/>
				</MotiView>
			)}
			{!isLoading &&
				!showCodePreview &&
				(data.uiType === 'file' || data.uiType === 'database') && (
					<MotiView
						key="code-change"
						from={{ opacity: 0, translateY: -6 }}
						animate={{ opacity: 1, translateY: 0 }}
						exit={{ opacity: 0, translateY: 6 }}
						transition={{ type: 'timing', duration: 300 }}
						style={styles.fileChangeContainer(theme)}
					>
						<CodeChangeBlock isCancelled={isCancelled} data={data} />
					</MotiView>
				)}
		</AnimatePresence>
	)
}

const styles = defineStyles({
	fileChangeContainer: (theme: Theme) => ({
		flexDirection: 'row',
		gap: 12,
		borderWidth: 1,
		borderRadius: 8,
		borderColor: colors[theme].gray[75],
		paddingVertical: 10,
		paddingHorizontal: 20,
		marginLeft: 28,
		marginRight: 20
	}),
	alignCenter: {
		alignItems: 'center'
	}
})
